select id, host, log_ts, status_code, payload_json, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, coalesce(context['region'], 'direct') as region_or_default, get_json_object(payload_json, '$.duration') as duration_text, coalesce(context['version'], 'unknown') as version_or_default, coalesce(context['trace'], 'none') as trace_or_default from app_logs
